// peer.min.js — WebRTC 文本透传最小 demo（无错误处理，仅供阅读/演示）
// 用法: 发起方 node peer.min.js offer ；应答方 node peer.min.js answer
// 信令: 把对端打印的一行 token 粘贴进来（offer 粘一次 answer，answer 粘一次 offer）
// 行为: 连接后双方输入文本回车发送；answer 收到后原样回传，offer 打印收到的回显
import { RTCPeerConnection } from "werift";
import * as readline from "node:readline";

const role = process.argv[2] === "offer" ? "offer" : "answer";
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
const ask = (q) => new Promise((r) => rl.question(q, (a) => r(a)));

const pc = new RTCPeerConnection({ iceServers: [{ urls: "stun:stun.l.google.com:19302" }] });

// offer 必须先建通道再生成 offer，否则 werift 不做 ICE gather，SDP 里没有候选
let dc = role === "offer" ? pc.createDataChannel("chat") : null; // answer 侧由 ondatachannel 赋值

// 只有 answer 做 loop back（双方都回传会无限乒乓），offer 负责打印回显
if (role === "answer") {
  pc.ondatachannel = ({ channel }) => {
    dc = channel;
    channel.onMessage.subscribe((msg) => {
      console.log("[收到]", msg);
      channel.send(msg); // 原样回传
    });
  };
} else {
  dc.onMessage.subscribe((msg) => console.log("[echo]", msg));
}

pc.connectionStateChange.subscribe((s) => console.log("连接状态:", s));

// 信令 token = base64url({type, sdp})。werift 的 setLocalDescription 返回值里
// sdp 是空的，必须用 pc.localDescription；它会等 ICE gathering 完成才返回，
// 所以 SDP 自带全部候选，双方各交换一行即可（非 trickle）
// 注意 type/sdp 要显式取：SessionDescription 的字段是原型 getter，直接
// JSON.stringify(localDescription) 会把 type 丢掉
const encode = (d) =>
  Buffer.from(JSON.stringify({ type: d.type, sdp: d.sdp }), "utf8").toString("base64url");
const decode = (line) => JSON.parse(Buffer.from(line.trim(), "base64url").toString("utf8"));

async function main() {
  if (role === "offer") {
    await pc.setLocalDescription(await pc.createOffer());
    console.log("== 把这行发给对端 ==\n" + encode(pc.localDescription) + "\n");
    await pc.setRemoteDescription(decode(await ask("粘贴对端的 answer token: ")));
  } else {
    await pc.setRemoteDescription(decode(await ask("粘贴对端的 offer token: ")));
    await pc.setLocalDescription(await pc.createAnswer());
    console.log("== 把这行发回对端 ==\n" + encode(pc.localDescription) + "\n");
  }

  rl.on("line", (line) => {
    if (line && dc && dc.readyState === "open") dc.send(line);
  });
  console.log("已就绪：输入文本回车发送");
}

main();
